"use client";

import { useEffect, useRef, useTransition } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Search } from "lucide-react";

export function ContactsSearch({ query }: { query: string }) {
  const router = useRouter();
  const params = useSearchParams();
  const input = useRef<HTMLInputElement>(null);
  const lastSubmitted = useRef(query);
  const [pending, startTransition] = useTransition();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Navigation and browser Back/Forward also update the controlled field.
  useEffect(() => {
    // A response to our search must not overwrite text typed while it loaded.
    if (query === lastSubmitted.current && input.current?.value !== query)
      return;
    if (timer.current) clearTimeout(timer.current);
    if (input.current) input.current.value = query;
  }, [query, params]);
  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  function search(next: string) {
    if (timer.current) clearTimeout(timer.current);
    lastSubmitted.current = next;
    const nextParams = new URLSearchParams(params.toString());
    nextParams.delete("page");
    if (next) nextParams.set("q", next);
    else nextParams.delete("q");
    const suffix = nextParams.toString();
    startTransition(() =>
      router.replace(`/contacts${suffix ? `?${suffix}` : ""}`, {
        scroll: false,
      }),
    );
  }
  return (
    <form
      method="get"
      action="/contacts"
      role="search"
      aria-busy={pending}
      onSubmit={(event) => {
        event.preventDefault();
        search(input.current?.value ?? "");
      }}
      className="field-focus-wrapper flex h-[52px] items-center gap-3 rounded-[var(--appearance-radius,16px)] border border-[var(--contacts-border)] bg-[var(--contacts-surface)] px-[18px]"
    >
      <Search
        aria-hidden="true"
        size={18}
        className="shrink-0 text-[var(--contacts-muted)]"
      />
      <label htmlFor="contact-search" className="sr-only">
        Search contacts
      </label>
      <input
        id="contact-search"
        type="search"
        name="q"
        ref={input}
        defaultValue={query}
        maxLength={160}
        autoComplete="off"
        placeholder="Search names, emails, or companies…"
        className="h-full min-w-0 flex-1 bg-transparent text-sm"
        onChange={(event) => {
          const next = event.target.value;
          if (timer.current) clearTimeout(timer.current);
          timer.current = setTimeout(() => search(next), 250);
        }}
      />
    </form>
  );
}
